class RegistryContract(unittest.TestCase):
    maxDiff = 1500

    def setUp(self):
        self.assertTrue(REGISTRY.is_file(), "required root-readers.tsv is missing")
        self.text = REGISTRY.read_text(encoding="utf-8")
        # [LAW:single-enforcer] The production parser owns TSV shape validation.
        self.rows = parse_registry(self.text)

    def assert_kind(self, kind, expected):
        self.assertCountEqual([r for r in self.rows if r.kind == kind], expected)

    def test_kind_counts(self):
        self.assertEqual(Counter(r.kind for r in self.rows if not is_growth(r)), {
            "REPLACE": 74, "RENAME": 2, "INSTALL": 3,
            "CHECK": 16, "STOP": 14, "RECORD": 794,
        })

    def test_replace_edits_and_counts(self):
        self.assert_kind("REPLACE", EXPECTED_REPLACE)

    def test_rename_sources_and_destinations(self):
        self.assert_kind("RENAME", EXPECTED_RENAME)

    def test_install_sources_and_destinations(self):
        self.assert_kind("INSTALL", EXPECTED_INSTALL)

    def test_reader_checks_and_gitdir(self):
        self.assert_kind("CHECK", EXPECTED_CHECK)

    def test_process_classes(self):
        self.assert_kind("STOP", EXPECTED_STOP)

    def test_record_operands_and_reasons(self):
        self.assertCountEqual([r for r in self.rows
                               if isinstance(r, Record) and not is_growth(r)], EXPECTED_RECORD)

    def test_paths_are_relative_inside_m_and_absolute_outside(self):
        for row in self.rows:
            operands = {
                Replace: ("path",), Rename: ("src", "dst"),
                Install: ("src", "dst"), Record: ("prefix",),
                Check: ("path",), Stop: (),
            }[type(row)]
            for field in operands:
                value = getattr(row, field)
                with self.subTest(kind=row.kind, path=value):
                    self.assertFalse(value == M or value.startswith(M + "/"))
                    self.assertFalse(value.startswith("~"))
                    self.assertNotIn("*", value)
            if isinstance(row, Install):
                self.assertFalse(row.src.startswith("/"))
                self.assertTrue(row.dst.startswith("/"))

    def test_no_edit_below_outside_rename(self):
        sources = [r.src for r in self.rows
                   if isinstance(r, Rename) and r.src.startswith("/")]
        targets = [r.path for r in self.rows if isinstance(r, Replace)]
        targets += [r.dst for r in self.rows if isinstance(r, Install)]
        for src in sources:
            for target in targets:
                with self.subTest(source=src, target=target):
                    self.assertFalse(
                        target == src or target.startswith(src + "/"),
                        "W12(c): edit below an outside-M RENAME source",
                    )

    def test_records_never_mask_live_replacements(self):
        records = [r for r in self.rows if isinstance(r, Record)]
        for live in (r for r in self.rows if isinstance(r, Replace)):
            for record in records:
                self.assertFalse(
                    live.path == record.prefix or
                    live.path.startswith(record.prefix + "/"),
                    (live.path, record.prefix),
                )

    def test_replacements_pass_pre_and_post_on_fixture_bytes(self):
        edits = [r for r in self.rows if isinstance(r, Replace)]
        before, after, measured = {}, {}, {}
        for index, row in enumerate(self.rows):
            if isinstance(row, Replace):
                count = 2 if row.count == "measured" else row.count
                fixture = (row.old.encode() + b"\x00unrelated\xff\x00") * count
                result = fixture.replace(row.old.encode(), row.new.encode())
                before[row.path, row.old] = fixture.count(row.old.encode())
                after[row.path, row.old] = result.count(row.old.encode())
                after[row.path, row.new] = result.count(row.new.encode())
                if row.count == "measured":
                    measured[index] = count
        pre = classify(rows=self.rows, stage="pre",
                       hits={r.path: before[r.path, r.old] for r in edits},
                       counts=before, old_root_exists=True, measured_counts={})
        self.assertEqual(pre.findings, ())
        self.assertEqual(dict(pre.measured_counts), measured)
        self.assertEqual({kind for _, kind in pre.classifications}, {"LIVE"})
        post = classify(rows=self.rows, stage="post", hits={},
                        counts=after, old_root_exists=False,
                        measured_counts=dict(pre.measured_counts))
        self.assertEqual(post.findings, ())

    def test_backup_table_replaces_p_rows_with_r_rows(self):
        row, = [r for r in self.rows if isinstance(r, Replace)
                and r.path == "code/ops/backup/backup_pairs.tsv"]
        header = "reader\tsource\tdestination\texcludes\n"
        fixture = header + row.old
        self.assertEqual(fixture.count(row.old), 1)
        repaired = fixture.replace(row.old, row.new)
        pairs = list(csv.DictReader(io.StringIO(repaired), delimiter="\t"))
        self.assertEqual([p["reader"] for p in pairs], ["ssd", "gdrive", "intel"])
        self.assertEqual({p["source"] for p in pairs}, {R})
        self.assertEqual([p["destination"] for p in pairs], [
            H + "/Backups/memit/arhugula-persistent-memory",
            "gdrive:memit-backup/arhugula-persistent-memory", "HOLD",
        ])
        self.assertEqual({p["excludes"] for p in pairs}, {"backup_mirror.R.excludes"})
        self.assertEqual(repaired.count(row.old), 0)
        self.assertEqual(repaired.count(row.new), 1)
        self.assertTrue(repaired.startswith(header))

    def test_csv_multiline_round_trip_in_temporary_fixture(self):
        scratch = tempfile.TemporaryDirectory()
        self.addCleanup(scratch.cleanup)
        fixture = Path(scratch.name) / "registry.tsv"
        with fixture.open("w", encoding="utf-8", newline="") as stream:
            writer = csv.writer(stream, delimiter="\t", lineterminator="\n")
            for row in self.rows:
                fields = astuple(row)
                writer.writerow((row.kind, *fields[:-1]))
        self.assertEqual(parse_registry(fixture.read_text()), self.rows)


